<?php require_once __DIR__.'/../_bootstrap.php';$u=user();$s=db()->prepare('SELECT r.*,p.name,p.unique_identifier,s.profit,s.selling_price,u.full_name seller_name,u.shop_name,u.phone seller_phone FROM returns r JOIN products p ON p.id=r.product_id JOIN sales s ON s.id=r.sale_id JOIN users u ON u.id=r.seller_id WHERE r.seller_id=? ORDER BY r.returned_at DESC');$s->execute([$u['id']]);out(['success'=>true,'returns'=>$s->fetchAll()]);
